package com.own.order.service;
import com.own.order.domain.SubOrderStatus; import com.own.order.domain.TradeSubOrder; import com.own.order.repository.TradeSubOrderRepository; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class AutoReceiptScheduler { private final TradeSubOrderRepository repository; private final OrderService service; private final int days; public AutoReceiptScheduler(TradeSubOrderRepository repository,OrderService service,@Value("${trade.order.auto-receipt-days:7}") int days){this.repository=repository;this.service=service;this.days=days;} @Scheduled(fixedDelayString="${trade.order.auto-receipt-delay-millis:3600000}") public void receiveShippedOrders(){if(days<=0)return;Date deadline=new Date(System.currentTimeMillis()-days*24L*60L*60L*1000L);for(TradeSubOrder sub:repository.findByStatusAndShippedAtBefore(SubOrderStatus.SHIPPED,deadline))service.autoReceive(sub.getSubOrderNo());} }
